1	/**
2	 * Turns arbitrary user text into a safe FTS5 MATCH expression.
3	 *
4	 * Raw input passed to MATCH is a top crash source: `"`, `*`, `:`, `-`, `(`, and
5	 * the bare operators `OR` / `NEAR` / `AND` / `NOT` can throw or behave oddly. We
6	 * tokenize on whitespace, drop tokens with no word characters, and wrap each
7	 * remaining token in double quotes (doubling any embedded quote). Quoted tokens
8	 * are treated as literal phrases by FTS5, so operators are neutralized. Tokens are
9	 * joined with spaces, which FTS5 reads as implicit AND.
10	 */
11	
12	/** Builds a safe MATCH string, or "" when the input has no usable terms. */
13	export function sanitizeFtsQuery(input: string): string {
14	  const tokens = input.trim().split(/\s+/).filter(Boolean);
15	  const quoted: string[] = [];
16	  for (const token of tokens) {
17	    // Keep only tokens that contain at least one alphanumeric/underscore character.
18	    if (!/[\p{L}\p{N}_]/u.test(token)) continue;
19	    quoted.push(`"${token.replace(/"/g, '""')}"`);
20	  }
21	  return quoted.join(" ");
