1	/**
2	 * Resolves where chisme stores its global, multi-repo index.
3	 *
4	 * Uses each OS's native convention: `~/Library/Application Support` and
5	 * `~/Library/Caches` on macOS, `%APPDATA%` on Windows, and the XDG Base Directory
6	 * spec on Linux. `CHISME_DATA_DIR` overrides the data dir everywhere (tests and
7	 * power users); XDG vars are honored on Linux only.
8	 */
9	import { homedir } from "node:os";
10	import { join } from "node:path";
11	import { mkdirSync } from "node:fs";
12	
13	/** Root directory for chisme's persistent data (the SQLite index lives here). */
14	export function dataDir(): string {
15	  const override = process.env.CHISME_DATA_DIR;
16	  if (override) return override;
17	
18	  if (process.platform === "darwin") {
19	    return join(homedir(), "Library", "Application Support", "chisme");
20	  }
21	
22	  if (process.platform === "win32") {
23	    const appData = process.env.APPDATA ?? join(homedir(), "AppData", "Roaming");
24	    return join(appData, "chisme");
25	  }
26	
27	  // Linux and other unix: XDG.
28	  const xdg = process.env.XDG_DATA_HOME;
29	  if (xdg) return join(xdg, "chisme");
30	  return join(homedir(), ".local", "share", "chisme");
31	}
32	
33	/** Absolute path to the global index database. */
34	export function databasePath(): string {
35	  return join(dataDir(), "chisme.db");
36	}
37	
38	/** Directory transformers.js uses to cache downloaded embedding models. */
39	export function modelCacheDir(): string {
40	  if (process.platform === "darwin") {
41	    return join(homedir(), "Library", "Caches", "chisme", "models");
42	  }
43	
44	  // Linux and other unix: XDG cache. (Windows has no native ML-cache convention
45	  // we rely on, so it falls through to the same per-user cache dir.)
46	  const xdg = process.env.XDG_CACHE_HOME;
47	  const base = xdg ? join(xdg, "chisme") : join(homedir(), ".cache", "chisme");
48	  return join(base, "models");
49	}
50	
51	/** Ensures the data directory exists and returns it. */
52	export function ensureDataDir(): string {
53	  const dir = dataDir();
54	  mkdirSync(dir, { recursive: true });
55	  return dir;
56	}
57

